create or replace function app.phase2_intake(p_referral uuid,p_packet boolean default false) returns boolean language plpgsql stable security definer set search_path='' as $$ declare ref public.referrals; role_name text:=app.current_role(); begin
if app.phase2_staff_id() is null or role_name is null or not (role_name='intake_coordinator' or (p_packet and role_name='clinical_coordinator')) then return false; end if;
select * into ref from public.referrals where id=p_referral and org_id=app.org_id(); if ref.id is null or ref.status='declined' then return false; end if;
if role_name='intake_coordinator' and exists(select 1 from public.intake_checklists where referral_id=ref.id and org_id=ref.org_id and completed_at is not null) then return false; end if;
return ref.linked_patient_id is null or not app.phase2_restricted(ref.linked_patient_id); end $$;
create or replace function app.phase2_packet_access(p_referral uuid,p_part2 boolean) returns boolean language plpgsql stable security definer set search_path='' as $$ declare p uuid; begin
select linked_patient_id into p from public.referrals where id=p_referral and org_id=app.org_id();
if app.phase2_intake(p_referral,true) then return not p_part2 or app.phase2_treatment_consent(p); end if;
return p is not null and exists(select 1 from public.intake_checklists where org_id=app.org_id() and referral_id=p_referral and completed_at is not null) and (app.phase2_is_team(p,'care_manager') or app.phase2_is_team(p,'clinician')) and app.phase2_chart_read(p,'documents') and (not p_part2 or exists(select 1 from app.can_access('sud_treatment',p) where level<>'none')); end $$;
create or replace function app.packet_documents_view(p_referral uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$ declare p uuid; begin
select linked_patient_id into p from public.referrals where id=p_referral and org_id=app.org_id();
if not app.phase2_intake(p_referral,true) and not (p is not null and app.phase2_chart_read(p,'documents') and (app.phase2_is_team(p,'care_manager') or app.phase2_is_team(p,'clinician')) and exists(select 1 from public.intake_checklists where org_id=app.org_id() and referral_id=p_referral and completed_at is not null)) then return '[]'::jsonb; end if;
return coalesce((select jsonb_agg(case when app.phase2_packet_access(d.referral_id,d.part2_tagged) then jsonb_build_object('id',d.id,'locked',false,'document_type',d.document_type,'source',d.source,'file_name',d.file_name,'contentAvailable',false) else jsonb_build_object('id',d.id,'locked',true,'reason','Part 2 — needs consent covering intake/treatment') end order by d.id) from public.packet_documents d where org_id=app.org_id() and referral_id=p_referral),'[]'::jsonb); end $$;
alter policy own_restricted_open on public.restricted_record_opens using(org_id=app.org_id() and (account_id=app.account_id() or app.current_role() in ('sys_admin','credentialing_coordinator')));
alter policy packet_needs on public.intake_packet_needs using(org_id=app.org_id() and exists(select 1 from public.referrals r where r.id=intake_packet_needs.referral_id and r.org_id=intake_packet_needs.org_id and ((app.phase2_intake(r.id) and (not intake_packet_needs.part2_tagged or app.phase2_treatment_consent(r.linked_patient_id))) or (exists(select 1 from public.intake_checklists c where c.referral_id=r.id and c.org_id=r.org_id and c.completed_at is not null) and (app.phase2_is_team(r.linked_patient_id,'clinician') or app.phase2_is_team(r.linked_patient_id,'care_manager')) and app.phase2_chart_read(r.linked_patient_id,'sdoh') and (not intake_packet_needs.part2_tagged or exists(select 1 from app.can_access('sud_treatment',r.linked_patient_id) where level<>'none'))))));
revoke execute on function public.phase2_command(text,uuid,jsonb,text),app.phase2_run_action(text,uuid,jsonb,text) from authenticated;
comment on function app.phase2_run_action(text,uuid,jsonb,text) is 'Phase 2 command prototype remains closed pending complete registry contract parity. Do not grant or call from runtime.';